with city_rows(name,slug) as (values ('Marseille','marseille'),('Talence','talence'),('Strasbourg','strasbourg'),('Paris','paris'),('Saint-Aubin','saint-aubin'),('Saint-Martin-d''Hères','saint-martin-dheres'),('Nice','nice')) insert into core.geographies(id,country_code,geography_type,name,slug,metadata,status) select md5('fr:city:'||slug)::uuid,'FR','city',name,slug,jsonb_build_object('source_tier','government_registry','source_system','ONISEP_UAI','normalization_batch','fr_idex_locations_v1'),'active' from city_rows on conflict(id) do update set name=excluded.name,slug=excluded.slug,metadata=coalesce(core.geographies.metadata,'{}'::jsonb)||excluded.metadata,status=excluded.status,updated_at=now(); with location_rows(uai,city_name,city_slug,location_name,address_line,postal_code,source_url) as (values ('0134009M','Marseille','marseille','Registered university address','58 boulevard Charles Livon','13284','https://www.onisep.fr/ressources/structures-enseignement/provence-alpes-cote-d-azur/bouches-du-rhone/aix-marseille-universite'),('0333298F','Talence','talence','Registered university address','351 cours de la Libération','33405','https://www.onisep.fr/ressources/structures-enseignement/nouvelle-aquitaine/gironde/universite-de-bordeaux'),('0673021V','Strasbourg','strasbourg','Registered university address','4 rue Blaise Pascal','67081','https://www.onisep.fr/ressources/structures-enseignement/grand-est/bas-rhin/universite-de-strasbourg'),('0755890V','Paris','paris','University headquarters','21 rue de l''École de Médecine','75006','https://www.sorbonne-universite.fr/'),('0912408Y','Saint-Aubin','saint-aubin','Registered university address','Route de l''Orme aux Merisiers, Espace technologique, bâtiment Discovery','91190','https://www.onisep.fr/ressources/structures-enseignement/ile-de-france/essonne/universite-paris-saclay'),('0756036D','Paris','paris','Registered university address','60 rue Mazarine','75006','https://www.onisep.fr/ressources/structures-enseignement/ile-de-france/paris/universite-paris-sciences-et-lettres-universite-psl'),('0383546Y','Saint-Martin-d''Hères','saint-martin-dheres','Registered university address','621 avenue Centrale','38400','https://www.onisep.fr/ressources/structures-enseignement/auvergne-rhone-alpes/isere/universite-grenoble-alpes'),('0062205P','Nice','nice','Registered university address','28 avenue de Valrose','06103','https://www.onisep.fr/ressources/structures-enseignement/provence-alpes-cote-d-azur/alpes-maritimes/universite-cote-d-azur'),('0755976N','Paris','paris','Registered university address','85 boulevard Saint-Germain','75006','https://www.onisep.fr/ressources/structures-enseignement/ile-de-france/paris/universite-paris-cite')), resolved as (select identity.institution_id,identity.uai,l.city_name,l.city_slug,l.location_name,l.address_line,l.postal_code,l.source_url,g.id geography_id from location_rows l join public.institution_identity_fr_v1 identity on identity.uai=l.uai join core.geographies g on g.country_code='FR' and g.geography_type='city' and g.slug=l.city_slug and g.status='active') insert into catalog.campuses(id,institution_id,name,city,locality,country_code,geography_id,locality_geography_id,address_line,postal_code,official_url,source_url,source_checked_at,metadata,status) select md5('fr:idex-location:'||uai)::uuid,institution_id,location_name,city_name,city_name,'FR',geography_id,geography_id,address_line,postal_code,source_url,source_url,now(),jsonb_build_object('record_scope','registered_institution_location','location_quality','verified_official','display_policy','preferred','source_tier','government_registry','source_system','ONISEP_UAI','uai',uai,'location_key','registered-head-office','coordinate_precision','not_asserted','campus_inventory_complete',false,'programme_assignment_verified',false,'normalization_batch','fr_idex_locations_v1'),'active' from resolved on conflict(id) do update set name=excluded.name,city=excluded.city,locality=excluded.locality,geography_id=excluded.geography_id,locality_geography_id=excluded.locality_geography_id,address_line=excluded.address_line,postal_code=excluded.postal_code,official_url=excluded.official_url,source_url=excluded.source_url,source_checked_at=excluded.source_checked_at,metadata=excluded.metadata,status=excluded.status,updated_at=now(); create or replace view public.institution_location_fr_v1 with(security_invoker=true) as select c.institution_id,c.id campus_id,c.name,g.name city_name,g.slug city_slug,coalesce(nullif(c.city,''),nullif(c.locality,'')) reported_city,c.region,c.address_line,c.postal_code,c.official_url,c.source_url,c.source_checked_at,c.metadata->>'location_quality' location_quality,c.metadata->>'record_scope' record_scope,c.metadata->>'uai' uai from catalog.campuses c join catalog.institutions i on i.id=c.institution_id and i.country_code='FR' left join core.geographies g on g.id=coalesce(c.locality_geography_id,c.geography_id) and g.status='active' where c.status<>'inactive' and c.metadata->>'location_quality'='verified_official'; revoke all on public.institution_location_fr_v1 from public,anon,authenticated; grant select on public.institution_location_fr_v1 to service_role; do $$ declare c int; begin select count(*) into c from public.institution_location_fr_v1; if c<>9 then raise exception 'Expected 9 FR locations, found %',c; end if; select count(*) into c from public.institution_location_fr_v1 where address_line is null or postal_code !~ '^[0-9]{5}$'; if c>0 then raise exception 'Invalid FR locations %',c; end if; end $$;;
